import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();

        s = s.replaceFirst("at", "@");
        s = s.replace("dot", ".");

        if (s.startsWith(".")) {
            s = "dot" + s.substring(1);
        }

        if (s.startsWith("@")) {
            s = s.replaceFirst("at", "@");
            s = "at" + s.substring(1);
        }

        if (s.endsWith(".")) {
            s = s.substring(0, s.length() - 1) + "dot";
        }

        System.out.println(s);
    }
}
